window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1a900c24113e9e0f"]={"versions": [{"id": "FIG-1a900c24113e9e0f", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Ausschnitt des formalen AUTOSAR-M2-Metamodells gemäß <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>, Release R20-11).\n</li><li><strong>Funktionale Einordnung:</strong> Definiert die abstrakte Metaklasse <code>ServiceNeeds</code> und deren domänenspezifische Spezialisierungen innerhalb des Software-Komponenten-Templates (<code>SwcInternalBehavior</code> / <code>BswInternalBehavior</code>).\n</li><li><strong>Technischer Zweck:</strong> Ermöglicht einer Software Component (SWC) oder einem BSW-Modul die deklarative Spezifikation von BSW-Dienstanforderungen (z. B. Watchdog, State Management, Kommunikation, Krypto, Diagnose). Diese Deklarationen dienen Upstream-Authoring- und Konfigurationstools als normative Eingabe zur automatischen Synthese von Service-Ports, RTE-Konnektoren und BSW-Modulkonfigurationen (ECUC) gemäß RS_SWCT_02060.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Basisklasse</h5>\n<ul class=\"fig-list\"><li><strong><code>ServiceNeeds</code> (abstrakt):</strong> Spezialisiert die AUTOSAR-Kernklasse <code>Identifiable</code> (erbt <code>shortName</code>, <code>category</code>, <code>uuid</code>). Dient als polymorphe Basis für alle BSW-Servicebedarfe.\n</li></ul>\n<h5 class=\"fig-section-h5\">Spezialisierungen &amp; Attribute (Generalisierungsbeziehungen <code>«isA»</code> auf <code>ServiceNeeds</code>)</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Metaklasse</th><th>Attribute &amp; Datentypen</th><th>Multiplizität</th><th>Semantik / BSW-Bindeglied</th></tr></thead><tbody><tr><td><strong><code>SupervisedEntityNeeds</code></strong></td><td><code>activateAtStart: Boolean</code>&lt;br&gt;<code>enableDeactivation: Boolean</code>&lt;br&gt;<code>expectedAliveCycle: TimeValue</code>&lt;br&gt;<code>maxAliveCycle: TimeValue</code>&lt;br&gt;<code>minAliveCycle: TimeValue</code>&lt;br&gt;<code>toleratedFailedCycles: PositiveInteger</code></td><td><code>[0..1]</code>&lt;br&gt;<code>[0..1]</code>&lt;br&gt;<code>[0..1]</code>&lt;br&gt;<code>[0..1]</code>&lt;br&gt;<code>[0..1]</code>&lt;br&gt;<code>[0..1]</code></td><td>Parametrisierung der Alive-Überwachung für den Watchdog Manager (<strong>WdgM</strong>). Definiert Erwartungswerte, Toleranzfenster und Initialzustand der Supervised Entity.</td></tr><tr><td><strong><code>ComMgrUserNeeds</code></strong></td><td><code>maxCommMode: MaxCommModeEnum</code></td><td><code>[0..1]</code></td><td>Anforderung an den Communication Manager (<strong>ComM</strong>). Steuert den maximal zulässigen Kommunikationsmodus.</td></tr><tr><td><strong><code>CryptoServiceNeeds</code></strong></td><td><code>algorithmFamily: String</code>&lt;br&gt;<code>algorithmMode: String</code>&lt;br&gt;<code>cryptoKeyDescription: String</code>&lt;br&gt;<code>maximumKeyLength: PositiveInteger</code></td><td><code>[0..1]</code>&lt;br&gt;<code>[0..1]</code>&lt;br&gt;<code>[0..1]</code>&lt;br&gt;<code>[0..1]</code></td><td>Legacy/Direktanforderung an den Crypto Service Manager (<strong>CSM</strong>); spezifiziert primitive Krypto-Eigenschaften, Algorithmusfamilie, Modus und Schlüssellängen.</td></tr><tr><td><strong><code>CryptoServiceJobNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Spezifikation jobbasierter Krypto-Operationen (Referenzierung von CSM-Job-Definitionen).</td></tr><tr><td><strong><code>GlobalSupervisionNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Globale Überwachungsanforderung über mehrere Entities hinweg im <strong>WdgM</strong>.</td></tr><tr><td><strong><code>EcuStateMgrUserNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Status-/Wakeup-/Shutdown-Bedarfe gegenüber dem ECU State Manager (<strong>EcuM</strong>).</td></tr><tr><td><strong><code>BswMgrNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Zustands- und Aktionsregeln für den Basic Software Manager (<strong>BswM</strong>).</td></tr><tr><td><strong><code>DltUserNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Registrierung von Log-/Trace-Funktionalität im Diagnostic Log and Trace (<strong>DLT</strong>).</td></tr><tr><td><strong><code>SyncTimeBaseMgrUserNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Zeitsynchronisations- und Trigger-Bedarfe an den <strong>StbM</strong>.</td></tr><tr><td><strong><code>DoIpServiceNeeds</code></strong> <em>(kursiv)</em></td><td><em>(abstrakt / spezialisierbar)</em></td><td>–</td><td>Diagnosedienste über IP-Netzwerke (<strong>DoIP</strong>).</td></tr><tr><td><strong><code>SecureOnBoardCommunicationNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Authentifizierungs- und Frischeanforderungen für PDUs (<strong>SecOC</strong>).</td></tr><tr><td><strong><code>VendorSpecificServiceNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Herstellererweiterungen für nicht-standardisierte BSW-Dienste.</td></tr></tbody></table></div>\n<h5 class=\"fig-section-h5\">Enumeration</h5>\n<ul class=\"fig-list\"><li><strong><code>MaxCommModeEnum</code>:</strong>\n<ul class=\"fig-list\"><li><code>none</code>: Keine Netzwerkkommunikation erlaubt.\n</li><li><code>silent</code>: Empfang aktiv, kein Senden (Bus-Listen-Modus).\n</li><li><code>full</code>: Volle Sende- und Empfangsberechtigung.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als M2-Strukturdiagramm bildet das Schaubild statische Metaklassen ab; das korrespondierende Entwurfs- und Laufzeitverhalten folgt der AUTOSAR-Methodik:</p>\n<ol class=\"fig-list\"><li><strong>Design-Phase (SWC-Deklaration):</strong>\n<ul class=\"fig-list\"><li>Der Komponentenentwickler instanziiert im ARXML ein Sub-Element von <code>ServiceNeeds</code> unterhalb von <code>SwcInternalBehavior.serviceNeed</code>.\n</li></ul>\n</li><li><strong>Integrations- &amp; Generierungs-Phase (Vertragserfüllung):</strong>\n<ul class=\"fig-list\"><li>Ein RTE-/BSW-Konfigurator analysiert die <code>ServiceNeeds</code>.\n</li><li><strong>Port-Synthese:</strong> Automatische Instanziierung von Service-Ports an der SWC (z. B. <code>PortPrototype</code> mit Interface <code>WdgM_AliveSupervision</code> oder <code>ComM_UserRequest</code>).\n</li><li><strong>Bsw-Mapping:</strong> Generierung korrespondierender ECUC-Container (z. B. <code>WdgMSupervisedEntity</code>, <code>ComMUser</code>, <code>CsmJob</code>).\n</li></ul>\n</li><li><strong>Laufzeit-Interaktion (ECU Runtime):</strong>\n<ul class=\"fig-list\"><li><strong>WdgM:</strong> SWC meldet periodisch Checkpoints über <code>Rte_Call_&lt;Port&gt;_CheckpointReached()</code>; WdgM evaluiert gegen <code>minAliveCycle</code> / <code>maxAliveCycle</code>. Bei Überschreitung von <code>toleratedFailedCycles</code> erfolgt Transition in den State <code>WDGM_GLOBAL_STATUS_EXPIRED</code>.\n</li><li><strong>ComM:</strong> SWC fordert via RTE-Service-Port <code>RequestComMode(COMM_FULL_COMMUNICATION)</code> an; BswM/ComM schalten die betreffenden Channel-Zustände synchron oder asynchron um.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Automatische Service-Port-Generierung:</strong> Werden <code>ServiceNeeds</code> in der SWC-Beschreibung deklariert, müssen Integratoren diese nicht manuell mit BSW-Instanzen verdrahten. Fehlerhafte oder fehlende <code>ServiceNeeds</code> verhindern die Konsistenzprüfung bei der ECU-Extrakt-Validierung.\n</li><li><strong>Optionale Multiplizität (<code>[0..1]</code>):</strong> Alle Attribute sind optional modelliert. Werden Grenzwerte weggelassen (z. B. <code>toleratedFailedCycles</code>), greifen die Default-Werte der jeweiligen BSW-Modulkonfiguration (ECUC) oder der Generator bricht mit einem Unspecified-Configuration-Fehler ab.\n</li><li><strong>Krypto-Migration:</strong> <code>CryptoServiceNeeds</code> adressiert klassische CSM-Krypto-Primitive. Für granulare, asynchrone Krypto-Jobs in neueren Releases (ab R4.3 / R4.4 / R20-11) ist primär <code>CryptoServiceJobNeeds</code> bzw. das Crypto-Key-Management-Pattern anzuwenden.\n</li><li><strong>Kopplungsrisiko:</strong> Spezifische Attribute in <code>SupervisedEntityNeeds</code> (z. B. Zykluszeiten) koppeln die logische Komponentenarchitektur an das Echtzeitverhalten des Ziel-OS. Bei Task-Perioden-Änderungen im System-Design müssen die <code>TimeValue</code>-Parameter zwingend synchronisiert werden, um fehlerhafte Watchdog-Triggerungen zu vermeiden.\n</li></ul>"}, {"id": "FIG-d96a265676a04e16", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Ausschnitt des formalen AUTOSAR-M2-Metamodells gemäß <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>, Release R20-11).\n</li><li><strong>Funktionale Einordnung:</strong> Definiert die abstrakte Metaklasse <code>ServiceNeeds</code> und deren domänenspezifische Spezialisierungen innerhalb des Software-Komponenten-Templates (<code>SwcInternalBehavior</code> / <code>BswInternalBehavior</code>).\n</li><li><strong>Technischer Zweck:</strong> Ermöglicht einer Software Component (SWC) oder einem BSW-Modul die deklarative Spezifikation von BSW-Dienstanforderungen (z. B. Watchdog, State Management, Kommunikation, Krypto, Diagnose). Diese Deklarationen dienen Upstream-Authoring- und Konfigurationstools als normative Eingabe zur automatischen Synthese von Service-Ports, RTE-Konnektoren und BSW-Modulkonfigurationen (ECUC) gemäß RS_SWCT_02060.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Basisklasse</h5>\n<ul class=\"fig-list\"><li><strong><code>ServiceNeeds</code> (abstrakt):</strong> Spezialisiert die AUTOSAR-Kernklasse <code>Identifiable</code> (erbt <code>shortName</code>, <code>category</code>, <code>uuid</code>). Dient als polymorphe Basis für alle BSW-Servicebedarfe.\n</li></ul>\n<h5 class=\"fig-section-h5\">Spezialisierungen &amp; Attribute (Generalisierungsbeziehungen <code>«isA»</code> auf <code>ServiceNeeds</code>)</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Metaklasse</th><th>Attribute &amp; Datentypen</th><th>Multiplizität</th><th>Semantik / BSW-Bindeglied</th></tr></thead><tbody><tr><td><strong><code>SupervisedEntityNeeds</code></strong></td><td><code>activateAtStart: Boolean</code>&lt;br&gt;<code>enableDeactivation: Boolean</code>&lt;br&gt;<code>expectedAliveCycle: TimeValue</code>&lt;br&gt;<code>maxAliveCycle: TimeValue</code>&lt;br&gt;<code>minAliveCycle: TimeValue</code>&lt;br&gt;<code>toleratedFailedCycles: PositiveInteger</code></td><td><code>[0..1]</code>&lt;br&gt;<code>[0..1]</code>&lt;br&gt;<code>[0..1]</code>&lt;br&gt;<code>[0..1]</code>&lt;br&gt;<code>[0..1]</code>&lt;br&gt;<code>[0..1]</code></td><td>Parametrisierung der Alive-Überwachung für den Watchdog Manager (<strong>WdgM</strong>). Definiert Erwartungswerte, Toleranzfenster und Initialzustand der Supervised Entity.</td></tr><tr><td><strong><code>ComMgrUserNeeds</code></strong></td><td><code>maxCommMode: MaxCommModeEnum</code></td><td><code>[0..1]</code></td><td>Anforderung an den Communication Manager (<strong>ComM</strong>). Steuert den maximal zulässigen Kommunikationsmodus.</td></tr><tr><td><strong><code>CryptoServiceNeeds</code></strong></td><td><code>algorithmFamily: String</code>&lt;br&gt;<code>algorithmMode: String</code>&lt;br&gt;<code>cryptoKeyDescription: String</code>&lt;br&gt;<code>maximumKeyLength: PositiveInteger</code></td><td><code>[0..1]</code>&lt;br&gt;<code>[0..1]</code>&lt;br&gt;<code>[0..1]</code>&lt;br&gt;<code>[0..1]</code></td><td>Legacy/Direktanforderung an den Crypto Service Manager (<strong>CSM</strong>); spezifiziert primitive Krypto-Eigenschaften, Algorithmusfamilie, Modus und Schlüssellängen.</td></tr><tr><td><strong><code>CryptoServiceJobNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Spezifikation jobbasierter Krypto-Operationen (Referenzierung von CSM-Job-Definitionen).</td></tr><tr><td><strong><code>GlobalSupervisionNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Globale Überwachungsanforderung über mehrere Entities hinweg im <strong>WdgM</strong>.</td></tr><tr><td><strong><code>EcuStateMgrUserNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Status-/Wakeup-/Shutdown-Bedarfe gegenüber dem ECU State Manager (<strong>EcuM</strong>).</td></tr><tr><td><strong><code>BswMgrNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Zustands- und Aktionsregeln für den Basic Software Manager (<strong>BswM</strong>).</td></tr><tr><td><strong><code>DltUserNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Registrierung von Log-/Trace-Funktionalität im Diagnostic Log and Trace (<strong>DLT</strong>).</td></tr><tr><td><strong><code>SyncTimeBaseMgrUserNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Zeitsynchronisations- und Trigger-Bedarfe an den <strong>StbM</strong>.</td></tr><tr><td><strong><code>DoIpServiceNeeds</code></strong> <em>(kursiv)</em></td><td><em>(abstrakt / spezialisierbar)</em></td><td>–</td><td>Diagnosedienste über IP-Netzwerke (<strong>DoIP</strong>).</td></tr><tr><td><strong><code>SecureOnBoardCommunicationNeeds</code></strong></td><td><code>verificationStatusIndicationMode: VerificationStatusIndicationModeEnum</code></td><td><code>[0..1]</code></td><td>Authentifizierungs- und Frischeanforderungen für PDUs (<strong>SecOC</strong>); steuert die Benachrichtigung bei Verifikationsergebnissen.</td></tr><tr><td><strong><code>VendorSpecificServiceNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Herstellerspezifische Serviceanforderungen außerhalb des AUTOSAR-Standards.</td></tr></tbody></table></div>\n<h5 class=\"fig-section-h5\">Aufzählungstypen (Enumerations)</h5>\n<ul class=\"fig-list\"><li><strong><code>MaxCommModeEnum</code>:</strong> Wertebereich für <code>ComMgrUserNeeds.maxCommMode</code>:\n<ul class=\"fig-list\"><li><code>none</code>: Keine Kommunikation gestattet.\n</li><li><code>silent</code>: Nur passiver Empfang gestattet.\n</li><li><code>full</code>: Vollständige Sende- und Empfangskommunikation.\n</li></ul>\n</li><li><strong><code>VerificationStatusIndicationModeEnum</code>:</strong> Wertebereich für <code>SecureOnBoardCommunicationNeeds.verificationStatusIndicationMode</code>:\n<ul class=\"fig-list\"><li><code>failureOnly</code>: Benachrichtigung nur bei fehlgeschlagener Verifikation.\n</li><li><code>failureAndSuccess</code>: Benachrichtigung bei erfolgreicher sowie fehlgeschlagener Verifikation.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als M2-Strukturdiagramm bildet das Schaubild statische Metaklassen ab; das korrespondierende Entwurfs- und Laufzeitverhalten folgt der AUTOSAR-Methodik:</p>\n<ol class=\"fig-list\"><li><strong>Design-Phase (SWC-Deklaration):</strong>\n<ul class=\"fig-list\"><li>Der Komponentenentwickler instanziiert im ARXML ein Sub-Element von <code>ServiceNeeds</code> unterhalb von <code>SwcInternalBehavior.serviceNeed</code>.\n</li></ul>\n</li><li><strong>Integrations- &amp; Generierungs-Phase (Vertragserfüllung):</strong>\n<ul class=\"fig-list\"><li>Ein RTE-/BSW-Konfigurator analysiert die <code>ServiceNeeds</code>.\n</li><li><strong>Port-Synthese:</strong> Automatische Instanziierung von Service-Ports an der SWC (z. B. <code>PortPrototype</code> mit Interface <code>WdgM_AliveSupervision</code> oder <code>ComM_UserRequest</code>).\n</li><li><strong>Bsw-Mapping:</strong> Generierung korrespondierender ECUC-Container (z. B. <code>WdgMSupervisedEntity</code>, <code>ComMUser</code>, <code>CsmJob</code>).\n</li></ul>\n</li><li><strong>Laufzeit-Interaktion (ECU Runtime):</strong>\n<ul class=\"fig-list\"><li><strong>WdgM:</strong> SWC meldet periodisch Checkpoints über <code>Rte_Call_&lt;Port&gt;_CheckpointReached()</code>; WdgM evaluiert gegen <code>minAliveCycle</code> / <code>maxAliveCycle</code>. Bei Überschreitung von <code>toleratedFailedCycles</code> erfolgt Transition in den State <code>WDGM_GLOBAL_STATUS_EXPIRED</code>.\n</li><li><strong>ComM:</strong> SWC fordert via RTE-Service-Port <code>RequestComMode(COMM_FULL_COMMUNICATION)</code> an; BswM/ComM schalten die betreffenden Channel-Zustände synchron oder asynchron um.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Automatische Service-Port-Generierung:</strong> Werden <code>ServiceNeeds</code> in der SWC-Beschreibung deklariert, müssen Integratoren diese nicht manuell mit BSW-Instanzen verdrahten. Fehlerhafte oder fehlende <code>ServiceNeeds</code> verhindern die Konsistenzprüfung bei der ECU-Extrakt-Validierung.\n</li><li><strong>Optionale Multiplizität (<code>[0..1]</code>):</strong> Alle Attribute sind optional modelliert. Werden Grenzwerte weggelassen (z. B. <code>toleratedFailedCycles</code>), greifen die Default-Werte der jeweiligen BSW-Modulkonfiguration (ECUC) oder der Generator bricht mit einem Unspecified-Configuration-Fehler ab.\n</li><li><strong>Krypto-Migration:</strong> <code>CryptoServiceNeeds</code> adressiert klassische CSM-Krypto-Primitive. Für granulare, asynchrone Krypto-Jobs in neueren Releases (ab R4.3 / R4.4 / R20-11) ist primär <code>CryptoServiceJobNeeds</code> bzw. das Crypto-Key-Management-Pattern anzuwenden.\n</li><li><strong>Kopplungsrisiko:</strong> Spezifische Attribute in <code>SupervisedEntityNeeds</code> (z. B. Zykluszeiten) koppeln die logische Komponentenarchitektur an das Echtzeitverhalten des Ziel-OS. Bei Task-Perioden-Änderungen im System-Design müssen die <code>TimeValue</code>-Parameter zwingend synchronisiert werden, um fehlerhafte Watchdog-Triggerungen zu vermeiden.\n</li></ul>"}, {"id": "FIG-5c01e7cdcfcfbc62", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Ausschnitt des formalen AUTOSAR-M2-Metamodells gemäß <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>, Release R20-11).\n</li><li><strong>Funktionale Einordnung:</strong> Definiert die abstrakte Metaklasse <code>ServiceNeeds</code> und deren domänenspezifische Spezialisierungen innerhalb des Software-Komponenten-Templates (<code>SwcInternalBehavior</code> / <code>BswInternalBehavior</code>).\n</li><li><strong>Technischer Zweck:</strong> Ermöglicht einer Software Component (SWC) oder einem BSW-Modul die deklarative Spezifikation von BSW-Dienstanforderungen (z. B. Watchdog, State Management, Kommunikation, Krypto, Diagnose). Diese Deklarationen dienen Upstream-Authoring- und Konfigurationstools als normative Eingabe zur automatischen Synthese von Service-Ports, RTE-Konnektoren und BSW-Modulkonfigurationen (ECUC) gemäß RS_SWCT_02060.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Basisklasse</h5>\n<ul class=\"fig-list\"><li><strong><code>ServiceNeeds</code> (abstrakt):</strong> Spezialisiert die AUTOSAR-Kernklasse <code>Identifiable</code> (erbt <code>shortName</code>, <code>category</code>, <code>uuid</code>). Dient als polymorphe Basis für alle BSW-Servicebedarfe.\n</li></ul>\n<h5 class=\"fig-section-h5\">Spezialisierungen &amp; Attribute (Generalisierungsbeziehungen <code>«isA»</code> auf <code>ServiceNeeds</code>)</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Metaklasse</th><th>Attribute &amp; Datentypen</th><th>Multiplizität</th><th>Semantik / BSW-Bindeglied</th></tr></thead><tbody><tr><td><strong><code>SupervisedEntityNeeds</code></strong></td><td><code>activateAtStart: Boolean</code>&lt;br&gt;<code>enableDeactivation: Boolean</code>&lt;br&gt;<code>expectedAliveCycle: TimeValue</code>&lt;br&gt;<code>maxAliveCycle: TimeValue</code>&lt;br&gt;<code>minAliveCycle: TimeValue</code>&lt;br&gt;<code>toleratedFailedCycles: PositiveInteger</code></td><td><code>[0..1]</code>&lt;br&gt;<code>[0..1]</code>&lt;br&gt;<code>[0..1]</code>&lt;br&gt;<code>[0..1]</code>&lt;br&gt;<code>[0..1]</code>&lt;br&gt;<code>[0..1]</code></td><td>Parametrisierung der Alive-Überwachung für den Watchdog Manager (<strong>WdgM</strong>). Definiert Erwartungswerte, Toleranzfenster und Initialzustand der Supervised Entity.</td></tr><tr><td><strong><code>ComMgrUserNeeds</code></strong></td><td><code>maxCommMode: MaxCommModeEnum</code></td><td><code>[0..1]</code></td><td>Anforderung an den Communication Manager (<strong>ComM</strong>). Steuert den maximal zulässigen Kommunikationsmodus.</td></tr><tr><td><strong><code>CryptoServiceNeeds</code></strong></td><td><code>algorithmFamily: String</code>&lt;br&gt;<code>algorithmMode: String</code>&lt;br&gt;<code>cryptoKeyDescription: String</code>&lt;br&gt;<code>maximumKeyLength: PositiveInteger</code></td><td><code>[0..1]</code>&lt;br&gt;<code>[0..1]</code>&lt;br&gt;<code>[0..1]</code>&lt;br&gt;<code>[0..1]</code></td><td>Legacy/Direktanforderung an den Crypto Service Manager (<strong>CSM</strong>); spezifiziert primitive Krypto-Eigenschaften, Algorithmusfamilie, Modus und Schlüssellängen.</td></tr><tr><td><strong><code>CryptoServiceJobNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Spezifikation jobbasierter Krypto-Operationen (Referenzierung von CSM-Job-Definitionen).</td></tr><tr><td><strong><code>GlobalSupervisionNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Globale Überwachungsanforderung über mehrere Entities hinweg im <strong>WdgM</strong>.</td></tr><tr><td><strong><code>EcuStateMgrUserNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Status-/Wakeup-/Shutdown-Bedarfe gegenüber dem ECU State Manager (<strong>EcuM</strong>).</td></tr><tr><td><strong><code>BswMgrNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Zustands- und Aktionsregeln für den Basic Software Manager (<strong>BswM</strong>).</td></tr><tr><td><strong><code>DltUserNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Registrierung von Log-/Trace-Funktionalität im Diagnostic Log and Trace (<strong>DLT</strong>).</td></tr><tr><td><strong><code>SyncTimeBaseMgrUserNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Zeitsynchronisations- und Trigger-Bedarfe an den <strong>StbM</strong>.</td></tr><tr><td><strong><code>DoIpServiceNeeds</code></strong> <em>(kursiv)</em></td><td><em>(abstrakt / spezialisierbar)</em></td><td>–</td><td>Diagnosedienste über IP-Netzwerke (<strong>DoIP</strong>).</td></tr><tr><td><strong><code>SecureOnBoardCommunicationNeeds</code></strong></td><td><code>verificationStatusIndicationMode: VerificationStatusIndicationModeEnum</code></td><td><code>[0..1]</code></td><td>Authentifizierungs- und Frischeanforderungen für PDUs (<strong>SecOC</strong>); steuert die Benachrichtigung bei Verifikationsergebnissen.</td></tr><tr><td><strong><code>VendorSpecificServiceNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Herstellerspezifische Serviceanforderungen außerhalb des AUTOSAR-Standards.</td></tr><tr><td><strong><code>ChargeManagerNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Dienstanforderungen bezüglich des Lade-Managements (<strong>Charge Manager</strong> / E-Mobility).</td></tr><tr><td><strong><code>GeneralPurposeTimerServiceNeeds</code></strong></td><td><em>(keine Attribute im Diagramm)</em></td><td>–</td><td>Dienstanforderungen an universelle Timer-Dienste (<strong>GPT</strong>).</td></tr><tr><td><strong><code>IndicatorStatusNeeds</code></strong></td><td><code>type: DiagnosticIndicatorTypeEnum</code></td><td><code>[0..1]</code></td><td>Dienstanforderungen an den Status diagnostischer optischer/akustischer Indikatoren (z. B. MIL) im Diagnostic Event Manager (<strong>Dem</strong>).</td></tr></tbody></table></div>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als M2-Strukturdiagramm bildet das Schaubild statische Metaklassen ab; das korrespondierende Entwurfs- und Laufzeitverhalten folgt der AUTOSAR-Methodik:</p>\n<ol class=\"fig-list\"><li><strong>Design-Phase (SWC-Deklaration):</strong>\n<ul class=\"fig-list\"><li>Der Komponentenentwickler instanziiert im ARXML ein Sub-Element von <code>ServiceNeeds</code> unterhalb von <code>SwcInternalBehavior.serviceNeed</code>.\n</li></ul>\n</li><li><strong>Integrations- &amp; Generierungs-Phase (Vertragserfüllung):</strong>\n<ul class=\"fig-list\"><li>Ein RTE-/BSW-Konfigurator analysiert die <code>ServiceNeeds</code>.\n</li><li><strong>Port-Synthese:</strong> Automatische Instanziierung von Service-Ports an der SWC (z. B. <code>PortPrototype</code> mit Interface <code>WdgM_AliveSupervision</code> oder <code>ComM_UserRequest</code>).\n</li><li><strong>Bsw-Mapping:</strong> Generierung korrespondierender ECUC-Container (z. B. <code>WdgMSupervisedEntity</code>, <code>ComMUser</code>, <code>CsmJob</code>).\n</li></ul>\n</li><li><strong>Laufzeit-Interaktion (ECU Runtime):</strong>\n<ul class=\"fig-list\"><li><strong>WdgM:</strong> SWC meldet periodisch Checkpoints über <code>Rte_Call_&lt;Port&gt;_CheckpointReached()</code>; WdgM evaluiert gegen <code>minAliveCycle</code> / <code>maxAliveCycle</code>. Bei Überschreitung von <code>toleratedFailedCycles</code> erfolgt Transition in den State <code>WDGM_GLOBAL_STATUS_EXPIRED</code>.\n</li><li><strong>ComM:</strong> SWC fordert via RTE-Service-Port <code>RequestComMode(COMM_FULL_COMMUNICATION)</code> an; BswM/ComM schalten die betreffenden Channel-Zustände synchron oder asynchron um.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Automatische Service-Port-Generierung:</strong> Werden <code>ServiceNeeds</code> in der SWC-Beschreibung deklariert, müssen Integratoren diese nicht manuell mit BSW-Instanzen verdrahten. Fehlerhafte oder fehlende <code>ServiceNeeds</code> verhindern die Konsistenzprüfung bei der ECU-Extrakt-Validierung.\n</li><li><strong>Optionale Multiplizität (<code>[0..1]</code>):</strong> Alle Attribute sind optional modelliert. Werden Grenzwerte weggelassen (z. B. <code>toleratedFailedCycles</code>), greifen die Default-Werte der jeweiligen BSW-Modulkonfiguration (ECUC) oder der Generator bricht mit einem Unspecified-Configuration-Fehler ab.\n</li><li><strong>Krypto-Migration:</strong> <code>CryptoServiceNeeds</code> adressiert klassische CSM-Krypto-Primitive. Für granulare, asynchrone Krypto-Jobs in neueren Releases (ab R4.3 / R4.4 / R20-11) ist primär <code>CryptoServiceJobNeeds</code> bzw. das Crypto-Key-Management-Pattern anzuwenden.\n</li><li><strong>Kopplungsrisiko:</strong> Spezifische Attribute in <code>SupervisedEntityNeeds</code> (z. B. Zykluszeiten) koppeln die logische Komponentenarchitektur an das Echtzeitverhalten des Ziel-OS. Bei Task-Perioden-Änderungen im System-Design müssen die <code>TimeValue</code>-Parameter zwingend synchronisiert werden, um fehlerhafte Watchdog-Triggerungen zu vermeiden.\n</li></ul>"}], "trans": [{"from": "FIG-1a900c24113e9e0f", "to": "FIG-d96a265676a04e16", "fr": "R20-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>SecureOnBoardCommunicationNeeds</strong>: Attribut <code>+ verificationStatusIndicationMode: VerificationStatusIndicationModeEnum [0..1]</code> ergänzt.\n</li><li><strong>VerificationStatusIndicationModeEnum</strong>: Enumeration neu aufgenommen mit den Literalen <code>failureOnly</code> und <code>failureAndSuccess</code>.\n</li></ul>"}, {"from": "FIG-d96a265676a04e16", "to": "FIG-5c01e7cdcfcfbc62", "fr": "R23-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>ChargeManagerNeeds</strong>: Metaklasse als Spezialisierung von <code>ServiceNeeds</code> neu aufgenommen.\n</li><li><strong>GeneralPurposeTimerServiceNeeds</strong>: Metaklasse als Spezialisierung von <code>ServiceNeeds</code> neu aufgenommen.\n</li><li><strong>IndicatorStatusNeeds</strong>: Metaklasse als Spezialisierung von <code>ServiceNeeds</code> neu aufgenommen mit dem Attribut <code>+ type: DiagnosticIndicatorTypeEnum [0..1]</code>.\n</li><li><strong>MaxCommModeEnum</strong>: Enumeration samt Literalen (<code>none</code>, <code>silent</code>, <code>full</code>) aus dem Diagramm entfernt.\n</li><li><strong>VerificationStatusIndicationModeEnum</strong>: Enumeration samt Literalen (<code>failureOnly</code>, <code>failureAndSuccess</code>) aus dem Diagramm entfernt.\n</li></ul>"}]};
